/**
 * NIMHANS Convention Centre floor plans, traced from the organiser's latest
 * venue artwork (issue #657): `events/indiafoss-2026/venue/floor-ground.svg`
 * and `floor-first.svg`. Paths are in each SVG's native coordinates, so each
 * floor carries its own viewBox.
 *
 * Room numbers follow the artwork's map key (`map-legend.svg`): ground floor
 * 1 Hall 1 (General Track), 2 Hall 2 (General Track), 3 Hall 3 (Devroom
 * Track), 4 Sponsor booths, 5 Hardware Showcase; first floor 6 Room 1
 * (Devroom Track), 7 Room 2 (BOF), 8 Room 3 (BOF), plus the Hall 1 balcony,
 * the Silent room and the Food area. Room `id`s are stable across artwork
 * revisions so programme locations keep resolving; only geometry changed.
 *
 * `marks` are the artwork's own furniture drawn back on top of the rooms:
 * number badges, amenity icons, baked labels and route arrows. A mark fill
 * of `'text'` follows the theme ink so baked labels stay legible in dark
 * mode; `'none'` draws stroke only.
 */
export interface FloorRoom {
  /** Bundle location id (matches `Location.id`). */
  id: string;
  name: string;
  /** Location id in the synthetic (2025) venue that stands in for this room. */
  key?: string;
  /** Seats, when the organisers say. */
  cap?: number;
  /** Room fill from the artwork's map key (legend colour). */
  c?: string;
  /** Label anchor in SVG units. */
  cx: number;
  cy: number;
  d: string;
}

export interface FloorWall {
  d: string;
  /** Stroke colour from the drawing: routes green, connectors darker green. */
  s: string;
  w: number;
}

export interface FloorMark {
  d: string;
  /** Fill from the drawing: a hex colour, `'none'` for stroke only, or `'text'` for theme ink. */
  f: string;
  s?: string;
  w?: number;
}

export interface Floor {
  id: FloorId;
  label: string;
  viewBox: string;
  outline: string;
  fill: string;
  rooms: FloorRoom[];
  podiums: string[];
  stairs: { d: string }[];
  walls: FloorWall[];
  marks: FloorMark[];
}

export type FloorId = 'ground' | 'first';

